class FrequencyTracker {
    private Map<Integer,Integer> cnt = new HashMap<>(), freq = new HashMap<>();
    public FrequencyTracker() {}
    private int get(Map<Integer,Integer> m, int k) { return m.getOrDefault(k, 0); }
    public void add(int number) {
        freq.merge(get(cnt, number), -1);
        cnt.merge(number, 1, Integer::sum);
        freq.merge(get(cnt, number), 1);
    }
    public void deleteOne(int number) {
        if (get(cnt, number) > 0) {
            freq.merge(get(cnt, number), -1);
            cnt.merge(number, -1, Integer::sum);
            freq.merge(get(cnt, number), 1);
        }
    }
    public boolean hasFrequency(int frequency) {
        return get(freq, frequency) > 0;
    }
}

