var FrequencyTracker = function() {
    this.cnt = new Map();
    this.freq = new Map();
};
FrequencyTracker.prototype.add = function(number) {
    const c = this.cnt.get(number) || 0;
    this.freq.set(c, (this.freq.get(c) || 0) - 1);
    this.cnt.set(number, c + 1);
    this.freq.set(c + 1, (this.freq.get(c + 1) || 0) + 1);
};
FrequencyTracker.prototype.deleteOne = function(number) {
    const c = this.cnt.get(number) || 0;
    if (c > 0) {
        this.freq.set(c, (this.freq.get(c) || 0) - 1);
        this.cnt.set(number, c - 1);
        this.freq.set(c - 1, (this.freq.get(c - 1) || 0) + 1);
    }
};
FrequencyTracker.prototype.hasFrequency = function(frequency) {
    return (this.freq.get(frequency) || 0) > 0;
};
